let
    Demo = Binary.Decompress(Binary.FromText("", BinaryEncoding.Base64), Compression.Deflate),
    Source = if DataMode = "Demo" then Demo else if DataMode = "Folder" then File.Contents(DataFolder & "/Performance.csv") else error "DataMode must be Demo or Folder",
    Parsed = Csv.Document(Source, [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    Headers = Table.PromoteHeaders(Parsed, [PromoteAllScalars=true]),
    Typed = Table.TransformColumnTypes(Headers, {{"PeriodID", type text}, {"ProjectID", type text}, {"Date", type date}, {"RecognizedRevenue", Currency.Type}, {"LaborCost", Currency.Type}, {"SubcontractCost", Currency.Type}, {"Expenses", Currency.Type}, {"ActualHours", Int64.Type}, {"PlannedHours", Int64.Type}, {"CostBudget", Currency.Type}, {"Invoiced", Currency.Type}, {"Collected", Currency.Type}}, "en-US")
in
    Typed
